import sys, docx
from docx.document import Document as _D
from docx.oxml.ns import qn
from docx.table import Table
from docx.text.paragraph import Paragraph

def iter_block_items(parent):
    if isinstance(parent, _D):
        parent_elm = parent.element.body
    else:
        parent_elm = parent._tc
    for child in parent_elm.iterchildren():
        if child.tag == qn('w:p'):
            yield Paragraph(child, parent)
        elif child.tag == qn('w:tbl'):
            yield Table(child, parent)

def dump(path):
    d = docx.Document(path)
    print("=== FILE:", path)
    cp = d.core_properties
    print("core: author=%r title=%r created=%r modified=%r lastmodby=%r subject=%r comments=%r" % (cp.author, cp.title, cp.created, cp.modified, cp.last_modified_by, cp.subject, cp.comments))
    for s in d.sections:
        for p in s.header.paragraphs:
            if p.text.strip(): print("[HEADER]", p.text)
        for p in s.footer.paragraphs:
            if p.text.strip(): print("[FOOTER]", p.text)
    for b in iter_block_items(d):
        if isinstance(b, Paragraph):
            t = b.text
            if t.strip():
                print("[%s] %s" % (b.style.name, t))
        else:
            print("[TABLE]")
            for r in b.rows:
                cells = []
                for c in r.cells:
                    cells.append(c.text.replace("\n"," / "))
                print("  | " + " | ".join(cells))
            print("[/TABLE]")
    # comments
    try:
        part = d.part
        for rel in part.rels.values():
            if 'comments' in rel.reltype:
                print("[COMMENTS PART]", rel.target_ref)
                from lxml import etree
                xml = rel.target_part.blob
                root = etree.fromstring(xml)
                for c in root.iter(qn('w:comment')):
                    txt = "".join(t.text or "" for t in c.iter(qn('w:t')))
                    print("  COMMENT by", c.get(qn('w:author')), c.get(qn('w:date')), ":", txt)
    except Exception as e:
        print("comment err", e)

for p in sys.argv[1:]:
    dump(p)
    print()
EOF
